import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as r,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"Lingma glossary","description":"Why TONGYI Lingma was renamed Qoder CN, why the IDE is not the plugin, and how Ask / Edit / Agent differ. No install steps, no price table.","frontmatter":{"title":"Lingma glossary","description":"Why TONGYI Lingma was renamed Qoder CN, why the IDE is not the plugin, and how Ask / Edit / Agent differ. No install steps, no price table.","domain":"product","tags":["coding-agent"],"role":"glossary"},"headers":[],"relativePath":"products/lingma/lingma-glossary.md","filePath":"products/lingma/lingma-glossary.md","lastUpdated":1787107158000}'),n={name:"products/lingma/lingma-glossary.md"};function i(s,t,d,l,g,h){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="lingma-glossary" tabindex="-1">Lingma glossary <a class="header-anchor" href="#lingma-glossary" aria-label="Permalink to &quot;Lingma glossary&quot;">​</a></h1><p>Explains names. Does not teach clicks. Tutorial: <a href="./lingma.html">lingma</a>. Map: <a href="./">index</a>.</p><h2 id="tongyi-lingma-qoder-cn" tabindex="-1">TONGYI Lingma / Qoder CN <a class="header-anchor" href="#tongyi-lingma-qoder-cn" aria-label="Permalink to &quot;TONGYI Lingma / Qoder CN&quot;">​</a></h2><p><strong>What it is:</strong> Alibaba Cloud&#39;s coding assistant. Marketing: code generation, ask, multi-file edits, coding agent. Help Center: the coding-focused sub-product of the Qoder CN series (formerly &quot;TONGYI Lingma&quot;).</p><p><strong>Why the rename:</strong> official date 2026-05-20. The suite now also covers office, terminal, digital-employee, and hosted-agent products. The public-cloud coding desktop app is now <strong>Qoder CN IDE</strong>; the JetBrains plugin continues.</p><p><strong>Role:</strong> maps to Copilot / Cursor (work inside an editor), not to a consumer chat site.</p><p>Official: <a href="https://help.aliyun.com/zh/lingma/what-is-qoder-cn" target="_blank" rel="noreferrer">What is Qoder CN</a>, <a href="https://help.aliyun.com/zh/lingma/introduction-of-lingma" target="_blank" rel="noreferrer">What is the Qoder CN series</a>.</p><h2 id="qoder-cn-ide-lingma-ide" tabindex="-1">Qoder CN IDE / Lingma IDE <a class="header-anchor" href="#qoder-cn-ide-lingma-ide" aria-label="Permalink to &quot;Qoder CN IDE / Lingma IDE&quot;">​</a></h2><p><strong>What it is:</strong> a standalone desktop IDE with the assistant built in. <strong>No plugin install.</strong> Marketing download pages still say <strong>Lingma IDE</strong>; Help Center and the new brand site say <strong>Qoder CN IDE</strong>.</p><p><strong>Why it exists:</strong> official iteration is concentrated here (and on the JetBrains plugin). When the VS Code plugin slows or stops, this is the official replacement.</p><p><strong>Versus the plugin:</strong> the plugin lives inside your current editor. The IDE is another client. Billing documents the upgrade as: uninstall Lingma IDE, install Qoder CN IDE.</p><h2 id="ide-plugins" tabindex="-1">IDE plugins <a class="header-anchor" href="#ide-plugins" aria-label="Permalink to &quot;IDE plugins&quot;">​</a></h2><p><strong>What they are:</strong> extensions for JetBrains IDEs, Visual Studio Code, and Visual Studio. Marketplace / package IDs still say <code>TONGYI Lingma</code> / <code>tongyi-lingma</code>.</p><p><strong>What they are not:</strong> not Qoder CN CLI, not QoderWork.</p><p><strong>VS Code:</strong> Help Center still teaches install and says updates will slow; billing says evolution stopped; docs.qoder.cn says unmaintained; the EN update log says discontinued. Treat it as installable, not as the current primary surface.</p><h2 id="ask-edit-agent" tabindex="-1">Ask / Edit / Agent <a class="header-anchor" href="#ask-edit-agent" aria-label="Permalink to &quot;Ask / Edit / Agent&quot;">​</a></h2><p>Three <strong>modes in one chat</strong>, not three products.</p><table tabindex="0"><thead><tr><th>Mode</th><th>What</th><th>Why it exists</th></tr></thead><tbody><tr><td>Ask</td><td>Answers only</td><td>Understand first</td></tr><tr><td>Edit</td><td>Multi-file edits in your range; faster</td><td>You already know the files</td></tr><tr><td>Agent</td><td>Plans, tools, terminal</td><td>You only give the goal</td></tr></tbody></table><p>You can switch inside one thread. Edit is missing on Lingma IDE / JetBrains. Visual Studio is Ask-only for now. How-to: <a href="./lingma-cookbook.html">cookbook</a>.</p><h2 id="nes-next-edit-suggestion" tabindex="-1">NES (Next Edit Suggestion) <a class="header-anchor" href="#nes-next-edit-suggestion" aria-label="Permalink to &quot;NES (Next Edit Suggestion)&quot;">​</a></h2><p><strong>What it is:</strong> predict the <strong>next edit</strong>, not the next line, from full-file context, recent edits, and the caret.</p><p><strong>What it is not:</strong> ordinary inline completion. IDE changelogs later call the upgrade <strong>NEXT</strong>.</p><p>Official: <a href="https://help.aliyun.com/zh/lingma/next-edit-suggestion" target="_blank" rel="noreferrer">NES</a>.</p><h2 id="project-awareness-memory" tabindex="-1">Project awareness / memory <a class="header-anchor" href="#project-awareness-memory" aria-label="Permalink to &quot;Project awareness / memory&quot;">​</a></h2><p><strong>Project awareness:</strong> infer framework, stack, relevant files, and errors from the task so you do not paste the whole repo.</p><p><strong>Memory:</strong> accumulate personal / project / issue memory during chat (<a href="https://help.aliyun.com/zh/lingma/memory" target="_blank" rel="noreferrer">Memory</a>).</p><p>These explain why opening related files helps. They do not mean &quot;the model was trained on your private repo&quot;. Model internals are out of scope; see <a href="/tech/fundamentals/LLM.html">Learn LLM</a>.</p><h2 id="quest-repowiki-subagent-experts" tabindex="-1">Quest / RepoWiki / Subagent / Experts <a class="header-anchor" href="#quest-repowiki-subagent-experts" aria-label="Permalink to &quot;Quest / RepoWiki / Subagent / Experts&quot;">​</a></h2><p>Listed on <a href="https://help.aliyun.com/zh/lingma/what-is-qoder-cn" target="_blank" rel="noreferrer">What is Qoder CN</a> as IDE-side upgrades:</p><ul><li><strong>Quest 2.0:</strong> split a complex coding task into steps.</li><li><strong>RepoWiki:</strong> project-level wiki.</li><li><strong>Subagent:</strong> child agents.</li><li><strong>Experts:</strong> specialist agents for frontend, backend, database, ops, test.</li></ul><p>Official: RepoWiki, Quest, and Subagent deduct Credits and are not turn-capped. This handbook does not split them into their own tutorials; operations live on <a href="https://docs.qoder.cn/" target="_blank" rel="noreferrer">docs.qoder.cn</a>.</p><h2 id="credits" tabindex="-1">Credits <a class="header-anchor" href="#credits" aria-label="Permalink to &quot;Credits&quot;">​</a></h2><p><strong>What it is:</strong> the usage unit introduced with seats on 2026-05-20. Extra Credits are sold as add-on packs. After the full-suite account upgrade, individual Credits can be shared across IDE / JetBrains / QoderWork / CLI and other suite apps.</p><p><strong>What it is not:</strong> unlimited free usage. The trial plan is explicitly limited, including a 2-week trial. Numbers: <a href="https://help.aliyun.com/zh/lingma/billing-description" target="_blank" rel="noreferrer">Billing</a>.</p><h2 id="not-this" tabindex="-1">Not this <a class="header-anchor" href="#not-this" aria-label="Permalink to &quot;Not this&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Actually</th><th>This site</th></tr></thead><tbody><tr><td><strong>Tongyi Qianwen / Qwen</strong></td><td>Consumer assistant (<a href="https://www.qianwen.com/" target="_blank" rel="noreferrer">qianwen.com</a>)</td><td>One map row, #83</td></tr><tr><td><strong>Model Studio (Bailian)</strong></td><td>Model / agent platform</td><td>One map row, #85</td></tr><tr><td><strong>Qoder CN CLI</strong></td><td>Terminal product</td><td>One map row</td></tr><tr><td><strong>QoderWork CN</strong></td><td>Office desktop agent</td><td>One map row</td></tr><tr><td><strong>QoderWake CN</strong></td><td>Digital employee</td><td>One map row</td></tr><tr><td><strong>Cloud Agents</strong></td><td>Hosted agent platform</td><td>One map row</td></tr><tr><td><strong>Taobao / ECS / payments</strong></td><td>Non-AI products</td><td>Out of scope</td></tr><tr><td>&quot;Lingma is just Qwen&#39;s IDE skin&quot;</td><td>False</td><td>Two products</td></tr><tr><td>&quot;It is only a VS Code plugin&quot;</td><td>False</td><td>Official default is IDE + JetBrains</td></tr></tbody></table><h2 id="renamed-or-retired" tabindex="-1">Renamed or retired <a class="header-anchor" href="#renamed-or-retired" aria-label="Permalink to &quot;Renamed or retired&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Old wording</th><th>Now</th></tr></thead><tbody><tr><td>AI Coding Assistant TONGYI Lingma</td><td>Qoder CN series from 2026-05-20</td></tr><tr><td>Lingma IDE</td><td>Qoder CN IDE; uninstall then reinstall on the official path</td></tr><tr><td>TONGYI Lingma plugin display name</td><td>Help Center: Qoder CN; marketplace ID still <code>Alibaba-Cloud.tongyi-lingma</code></td></tr><tr><td>Individual Pro limited-time free</td><td>Ended 2026-05-20 18:00; promo users moved to the community / trial tier</td></tr></tbody></table><p>Which door to open: <a href="./">learning map</a>.</p>',39)])])}const y=e(n,[["render",i]]);export{f as __pageData,y as default};
